let kugouLoginCache = null; // { cookie, info, fetchedAt } 缓存的完整登录信息（含 roleinfo 探测的会员状态）
async function probeKugouLogin(cookie) {
  const info = await Promise.race([
    loginInfo(cookie),
    new Promise(function (_resolve, reject) { setTimeout(function () { reject(new Error('timeout')); }, 10000); }),
  ]);
  kugouLoginCache = { cookie, info, fetchedAt: Date.now() };
  return info;
}

